/* global test expect */
import { DateTime } from "../src/luxon";

test("DateTime#plus works across the 100 barrier when passing through February", () => {
  const d = DateTime.fromISO("0099-12-31").plus({ day: 61 });
  expect(d.year).toBe(100);
  expect(d.month).toBe(3);
  expect(d.day).toBe(2);
});

test("objToLocalTS fix keeps the other barrier cases right", () => {
  const d = DateTime.fromISO("0099-12-31").plus({ day: 2 });
  expect([d.year, d.month, d.day]).toEqual([100, 1, 2]);
  const e = DateTime.fromISO("0100-01-02").minus({ day: 2 });
  expect([e.year, e.month, e.day]).toEqual([99, 12, 31]);
  const f = DateTime.utc(0, 1, 1).plus({ day: 59 });
  expect([f.year, f.month, f.day]).toEqual([0, 2, 29]);
  const g = DateTime.utc(99, 12, 31).plus({ day: 61 });
  expect([g.year, g.month, g.day]).toEqual([100, 3, 2]);
  const h = DateTime.utc(99, 12, 31).plus({ day: 366 });
  expect([h.year, h.month, h.day]).toEqual([101, 1, 1]);
});

/* global test expect */
import { Duration } from "../src/luxon";

const units = [
  "years",
  "quarters",
  "months",
  "weeks",
  "days",
  "hours",
  "minutes",
  "seconds",
  "milliseconds"
];

test("Duration#normalize can convert all unit pairs", () => {
  units.forEach(u1 => {
    units.forEach(u2 => {
      if (u1 === u2) return;
      const dur = Duration.fromObject({ [u1]: 2, [u2]: 2 }).normalize();
      expect(dur.isValid).toBe(true);
      expect(Number.isNaN(dur[u1])).toBe(false);
      expect(Number.isNaN(dur[u2])).toBe(false);
    });
  });
});

test("quarter/second conversions are exact", () => {
  expect(Duration.fromObject({ quarters: 1 }).as("seconds")).toBe(91 * 24 * 60 * 60);
  expect(Duration.fromObject({ seconds: 91 * 24 * 60 * 60 }).as("quarters")).toBe(1);
  expect(
    Duration.fromObject({ quarters: 1, seconds: 91 * 24 * 60 * 60 }).normalize().toObject()
  ).toEqual({ quarters: 2, seconds: 0 });
});

