});

test("A DateTime in an invalid FixedOffsetZone is itself invalid", () => {
  expect(DateTime.local().setZone(new FixedOffsetZone("blorp")).isValid).toBe(false);
  expect(DateTime.fromObject({ year: 2017, zone: new FixedOffsetZone("blorp") }).isValid).toBe(
